BEGIN;
SELECT plan(48);
SELECT set_config('test.owner',(SELECT id::text FROM auth.users WHERE email='insider@grida.co'),true);
INSERT INTO public.organization(name,display_name,owner_id) VALUES('m5-source-custody','Custody',current_setting('test.owner')::uuid);
SELECT set_config('test.org',(SELECT id::text FROM public.organization WHERE name='m5-source-custody'),true);
SELECT set_config('test.epoch',(SELECT source_epoch::text FROM grida_platform.authority),true);
SELECT set_config('test.claim',jsonb_build_object('organization_id',current_setting('test.org'),'product','grida-ai','operation','text','model','fixture/text','unit','cost_mills','policy_version','legacy-ai-v1','request_digest',repeat('a',64),'admission_observed_at',clock_timestamp()::text,'admission_expires_at',(clock_timestamp()+interval '50 seconds')::text)::text,true);
SELECT set_config('test.receipt',jsonb_build_object('organization_id',current_setting('test.org'),'product','grida-ai','operation','text','model','fixture/text','unit','cost_mills','policy_version','legacy-ai-v1','outcome','succeeded','quantity','0.000000000000000001','occurred_at',clock_timestamp()::text,'evidence_digest',repeat('b',64))::text,true);
SELECT is(public.platform_product_execution_claim('grida-ai','m5-retained-execution',current_setting('test.claim')::jsonb)->>'created','true','actual product claim precedes restore');
SELECT is(public.platform_product_execution_dispatch('grida-ai','m5-retained-execution')->>'dispatch','true','original claim dispatches once');
SET LOCAL ROLE service_role;
SELECT throws_ok($$SELECT grida_platform.begin_billing_maintenance(1,repeat('a',64))$$,'42501',NULL,'service cannot start operator maintenance');
SELECT throws_ok($$SELECT grida_platform.reconcile_source_work('50000000-0000-4000-8000-000000000001',repeat('a',64),'no_external_effect')$$,'42501',NULL,'service cannot classify unknown effects');
SELECT throws_ok($$SELECT grida_platform.quarantine_source_restore(current_setting('test.epoch')::uuid,'50000000-0000-4000-8000-000000000099',repeat('a',64))$$,'42501',NULL,'service cannot rotate source epoch');
SELECT is(public.platform_source_work_begin('50000000-0000-4000-8000-000000000001','provider_http',jsonb_build_object('request_digest',repeat('a',64)))->>'created','true','source provider admission commits');
SELECT is(public.platform_source_work_begin('50000000-0000-4000-8000-000000000001','provider_http',jsonb_build_object('request_digest',repeat('a',64)))->>'created','false','same admitted ID cannot redispatch');
SELECT throws_ok($$SELECT public.platform_source_work_begin('50000000-0000-4000-8000-000000000001','provider_http',jsonb_build_object('request_digest',repeat('b',64)))$$,'23505',NULL,'admitted ID cannot change request');
SELECT is(public.platform_source_work_begin('50000000-0000-4000-8000-000000000002','legacy_ai',jsonb_build_object('request_digest',repeat('c',64),'organization_id',current_setting('test.org'),'execution_id','legacy-accepted'))->>'created','true','legacy AI paid work is retained before provider');
SELECT is(public.platform_source_work_begin('50000000-0000-4000-8000-000000000004','provider_http',jsonb_build_object('request_digest',repeat('d',64)))->>'created','true','lost-response work identity retained');
RESET ROLE;
SELECT throws_ok($$SELECT grida_platform.transfer_billing_ownership(1,repeat('a',64))$$,'23505',NULL,'direct transfer requires prior maintenance');
SELECT is(grida_platform.begin_billing_maintenance(1,repeat('a',64))->>'phase','draining','operator closes new source admissions');
SELECT is(grida_platform.begin_billing_maintenance(1,repeat('a',64))->>'phase','draining','same maintenance intent is idempotent');
SELECT throws_ok($$SELECT grida_platform.begin_billing_maintenance(1,repeat('b',64))$$,'23505',NULL,'maintenance manifest cannot change');
SET LOCAL ROLE service_role;
SELECT throws_ok('UPDATE grida_billing.account SET customer_entitled=customer_entitled WHERE false','42501',NULL,'direct financial DML rejects during drain before touching rows');
SELECT throws_ok($$SELECT public.fn_billing_set_balance_cache(current_setting('test.org')::bigint,100,true)$$,'42501',NULL,'privileged old cache RPC cannot bypass maintenance');
SELECT throws_ok($$SELECT public.platform_source_work_begin('50000000-0000-4000-8000-000000000005','provider_http',jsonb_build_object('request_digest',repeat('a',64)))$$,'42501',NULL,'stale process cannot admit new provider request');
SELECT is(public.platform_source_work_capture('50000000-0000-4000-8000-000000000001','{"status":200,"request_id":"req_original","body_base64":"e30="}'::jsonb)->>'accepted','true','provider response is captured even after SQL writer stops');
SELECT throws_ok($$SELECT public.platform_source_work_finish('50000000-0000-4000-8000-000000000001')$$,'22023',NULL,'HTTP200 cannot certify parent projection');
SELECT is(public.platform_source_work_capture('50000000-0000-4000-8000-000000000002','{"quantity":"0.000000000000000001","unit":"cost_mills","outcome":"succeeded"}'::jsonb)->>'accepted','true','already admitted AI completion persists exact units during drain');
SELECT is(public.platform_source_work_begin('50000000-0000-4000-8000-000000000003','provider_http',jsonb_build_object('request_digest',repeat('e',64)),'50000000-0000-4000-8000-000000000002')->>'created','true','captured AI may finish original usage delivery while draining');
SELECT is(public.platform_source_work_capture('50000000-0000-4000-8000-000000000003','{"status":200,"request_id":"usage_original"}'::jsonb)->>'accepted','true','legacy usage response remains separate custody');
SELECT is(public.platform_source_work_finish('50000000-0000-4000-8000-000000000002')->>'accepted','true','original AI usage ACK completes its retained work');
RESET ROLE;
SELECT throws_ok($$SELECT grida_platform.transfer_billing_ownership(1,repeat('a',64))$$,'55000',NULL,'unclassified HTTP and unknown attempts block transfer');
SELECT is((SELECT state FROM grida_platform.admitted_work WHERE id='50000000-0000-4000-8000-000000000001'),'captured','successful HTTP with denied SQL remains unresolved');
SELECT grida_platform.reconcile_source_work('50000000-0000-4000-8000-000000000001',repeat('f',64),'provider_effect_verified');
SELECT grida_platform.reconcile_source_work('50000000-0000-4000-8000-000000000003',repeat('f',64),'provider_effect_verified');
SELECT grida_platform.reconcile_source_work('50000000-0000-4000-8000-000000000004',repeat('f',64),'target_custody');
SELECT is(grida_platform.transfer_billing_ownership(1,repeat('a',64))->>'owner','infra','only classified source custody permits monotonic fence');
SELECT is(grida_platform.transfer_billing_ownership(1,repeat('a',64))->>'epoch','2','identical fence retains owner epoch');
SET LOCAL ROLE service_role;
SELECT is(public.platform_source_work_capture('50000000-0000-4000-8000-000000000004','{"status":200,"request_id":"late_original"}'::jsonb)->>'state','reconciled','late original evidence preserves exported work disposition');
SELECT is(public.platform_source_work_capture('50000000-0000-4000-8000-000000000004','{"status":200,"request_id":"late_original"}'::jsonb)->>'accepted','true','exact late evidence replay acknowledges permanent receipt');
SELECT throws_ok($$SELECT public.platform_source_work_capture('50000000-0000-4000-8000-000000000004','{"status":500}'::jsonb)$$,'23505',NULL,'late evidence cannot overwrite original result');
SELECT throws_ok($$SELECT public.platform_source_work_begin('50000000-0000-4000-8000-000000000005','provider_http',jsonb_build_object('request_digest',repeat('a',64)))$$,'42501',NULL,'old process cannot start provider mutations after transfer');
SELECT is(public.platform_source_webhook_capture('stripe','evt_m5_original',convert_to('{"id":"evt_m5_original"}','UTF8'),'{"stripe-signature":"original"}'::jsonb)->>'accepted','true','raw verified ingress can be retained after source fence');
SELECT is(public.platform_source_webhook_ack('stripe','evt_m5_original',encode(sha256(convert_to('{"id":"evt_m5_original"}','UTF8')),'hex'))->>'acknowledged','true','exact committed target receipt acknowledges source archive');
RESET ROLE;
SELECT is((SELECT count(*)::integer FROM grida_platform.admitted_work_evidence WHERE work_id='50000000-0000-4000-8000-000000000004'),1,'late immutable evidence appears once for delta archive');
SELECT is((SELECT reconciliation_hash FROM grida_platform.admitted_work WHERE id='50000000-0000-4000-8000-000000000004'),repeat('f',64),'late result does not rewrite reviewed manifest');
SELECT grida_platform.quarantine_source_restore(current_setting('test.epoch')::uuid,'50000000-0000-4000-8000-000000000099',repeat('9',64));
SELECT throws_ok($$SELECT public.platform_gg_account_snapshots(jsonb_build_array(jsonb_build_object('id',current_setting('test.org'))),repeat('a',22))$$,'55000',NULL,'restored source cannot issue fresh authority before reconciliation');
SELECT is(public.platform_product_execution_receipt('grida-ai','m5-retained-execution',current_setting('test.receipt')::jsonb)->>'accepted','true','accepted product completion survives source epoch quarantine');
SELECT is((SELECT source_epoch::text FROM grida_platform.usage_outbox WHERE execution_id='m5-retained-execution'),current_setting('test.epoch'),'late completion retains original execution namespace');
SELECT is(public.platform_product_usage_page(100)->>'source_epoch','50000000-0000-4000-8000-000000000099','page identifies current source epoch');
SELECT is((SELECT event->>'source_epoch' FROM jsonb_array_elements(public.platform_product_usage_page(100)->'events') event WHERE event->>'execution_id'='m5-retained-execution'),current_setting('test.epoch'),'delivery uses immutable per-event epoch rather than current page epoch');
SELECT throws_ok($$SELECT grida_platform.reconcile_source_restore('50000000-0000-4000-8000-000000000099',repeat('8',64))$$,'23505',NULL,'restore cannot clear quarantine with unrelated evidence');
SELECT grida_platform.reconcile_source_restore('50000000-0000-4000-8000-000000000099',repeat('9',64));
SELECT is(public.platform_gg_account_snapshots(jsonb_build_array(jsonb_build_object('id',current_setting('test.org'))),repeat('b',22))->>'source_epoch','50000000-0000-4000-8000-000000000099','reviewed new authority can resume without reopening old billing');
SELECT is(public.platform_billing_owner()->>'owner','infra','source restore never rolls financial owner backwards');
SELECT is(public.platform_product_usage_ack(ARRAY[(SELECT event_id FROM grida_platform.usage_outbox WHERE execution_id='m5-retained-execution')])->>'acknowledged','true','old namespace event ACK retains permanent identity');
SELECT is((SELECT count(*)::integer FROM grida_platform.usage_outbox WHERE execution_id='m5-retained-execution'),1,'ACK never deletes historical event');
SELECT throws_ok($$SELECT grida_platform.quarantine_source_restore('50000000-0000-4000-8000-000000000099','50000000-0000-4000-8000-000000000099',repeat('9',64))$$,'22023',NULL,'restore must advance epoch');
SELECT throws_ok($$SELECT grida_platform.quarantine_source_restore('50000000-0000-4000-8000-000000000099',current_setting('test.epoch')::uuid,repeat('9',64))$$,'23505',NULL,'previously used original epoch cannot become new authority');
SELECT ok(NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace, LATERAL aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a WHERE n.nspname='grida_platform' AND a.grantee=0 AND a.privilege_type='EXECUTE'),'operator controls have no PUBLIC execute');
SELECT * FROM finish();
ROLLBACK;
